import type { RadarPoint } from '../types'

export function radarPointsToCsv(points: RadarPoint[]): Blob {
  const rows = ['x,y,z,range,azimuth,elevation,intensity']
  for (const point of points) {
    rows.push([
      point.x, point.y, point.z, point.range,
      point.azimuth, point.elevation, point.intensity,
    ].map((value) => Number(value).toFixed(6)).join(','))
  }
  return new Blob([rows.join('\n')], { type: 'text/csv;charset=utf-8' })
}

export function radarPointsToPly(points: RadarPoint[]): Blob {
  const header = [
    'ply',
    'format ascii 1.0',
    'comment generated by CoalForm radar-style simulator',
    `element vertex ${points.length}`,
    'property float x',
    'property float y',
    'property float z',
    'property float range',
    'property float azimuth',
    'property float elevation',
    'property uchar intensity',
    'end_header',
  ].join('\n')
  const body = points.map((point) => [
    point.x.toFixed(6), point.y.toFixed(6), point.z.toFixed(6),
    point.range.toFixed(6), point.azimuth.toFixed(6), point.elevation.toFixed(6),
    Math.max(0, Math.min(255, Math.round(point.intensity))),
  ].join(' ')).join('\n')
  return new Blob([`${header}\n${body}\n`], { type: 'application/octet-stream' })
}

export function downloadBlob(blob: Blob, filename: string): void {
  const url = URL.createObjectURL(blob)
  const anchor = document.createElement('a')
  anchor.href = url
  anchor.download = filename
  anchor.click()
  setTimeout(() => URL.revokeObjectURL(url), 1_000)
}
